public void testGetRGBThrowsIOException_2_oe() throws IOException {
    final PbmFileInfo pbmFileInfo = new PbmFileInfo(2764, 354, true);
    final byte[] byteArray = new byte[2];
    final InputStream inputStream = new ByteArrayInputStream(byteArray);
    inputStream.read(byteArray);

    try {
      pbmFileInfo.getRGB(inputStream);
    } catch(final IOException e) {
       assertEquals("PBM: Unexpected EOF",e.getMessage());
}
}

mut_method_definition:
@Override
    public int getRGB(final InputStream is) throws IOException {
        if (bitsInCache < 1) {
            final int bits = is.read();
            if (bits < 0) {
                throw new IOException("PBM: Unexpected EOF");
            }
            bitCache = 0xff & bits;
            bitsInCache += 8;
        }

        final int bit = 0x1 & (bitCache >> 7);
        bitCache <<= 1;
        bitsInCache--;

        if (bit == 0) {
            return 0xffffffff;
        }
        if (bit == 1) {
            return 0xff000000;
        }
        throw new IOException("PBM: bad bit: " + bit);
    }

